package com.careerpilot.modules.scheduling.entity;
import com.careerpilot.modules.assessment.entity.AssessmentAttempt;import com.careerpilot.modules.auth.entity.User;import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="scheduled_exam_candidates",uniqueConstraints=@UniqueConstraint(name="uk_scheduled_exam_candidate",columnNames={"scheduled_exam_id","candidate_user_id"}))@Getter @Setter @NoArgsConstructor public class ScheduledExamCandidate{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="scheduled_exam_id")private ScheduledExam scheduledExam;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="candidate_user_id")private User candidate;@OneToOne(fetch=FetchType.LAZY)@JoinColumn(name="attempt_id",unique=true)private AssessmentAttempt attempt;@Enumerated(EnumType.STRING)@Column(name="assignment_status",nullable=false,length=20)private AssignmentStatus assignmentStatus;@Column(name="assigned_at",nullable=false)private Instant assignedAt;@Column(name="started_at")private Instant startedAt;@Column(name="completed_at")private Instant completedAt;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@PrePersist void create(){if(id==null)id=UUID.randomUUID();Instant now=Instant.now();if(assignedAt==null)assignedAt=now;if(createdAt==null)createdAt=now;updatedAt=now;if(assignmentStatus==null)assignmentStatus=AssignmentStatus.ASSIGNED;}@PreUpdate void update(){updatedAt=Instant.now();}}
